import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import { hasLocale } from 'next-intl';
import { getTranslations, setRequestLocale } from 'next-intl/server';
import { site } from '@/config/site';
import { getPathname } from '@/i18n/navigation';
import { routing, type Locale, type Pathname } from '@/i18n/routing';

/** Social sharing image (generated by brand/tools/rasterize.mjs). */
export const ogImage = { url: '/og.png', width: 1200, height: 630, alt: site.name };

/** Validates the locale segment and enables static rendering for the page. */
export async function initPage(params: Promise<{ locale: string }>) {
  const { locale } = await params;
  if (!hasLocale(routing.locales, locale)) notFound();
  setRequestLocale(locale);
  return locale;
}

export function alternates(locale: Locale, href: Pathname) {
  return {
    canonical: getPathname({ locale, href }),
    languages: {
      ...Object.fromEntries(routing.locales.map((l) => [l, getPathname({ locale: l, href })])),
      'x-default': getPathname({ locale: routing.defaultLocale, href }),
    },
  };
}

type PageKey =
  | 'services'
  | 'platforms'
  | 'about'
  | 'approach'
  | 'industries'
  | 'careers'
  | 'contact'
  | 'imprint'
  | 'privacy';

export async function pageMetadata(
  params: Promise<{ locale: string }>,
  page: PageKey,
  href: Pathname
): Promise<Metadata> {
  const { locale } = await params;
  if (!hasLocale(routing.locales, locale)) return {};
  const t = await getTranslations({ locale, namespace: 'meta.pages' });
  const title = t(`${page}.title`);
  const description = t(`${page}.description`);
  return {
    title,
    description,
    alternates: alternates(locale, href),
    openGraph: {
      title: `${title} · ${site.name}`,
      description,
      url: getPathname({ locale, href }),
      images: [ogImage],
    },
    twitter: {
      card: 'summary_large_image',
      title: `${title} · ${site.name}`,
      description,
      images: [ogImage.url],
    },
  };
}
